// ============================================================================
// Standalone Dynamic Load Balancing settings — v1.0 TEST
// ============================================================================
// This flow uses GLOBAL context deliberately, because the Gast777 adapter and
// the standalone DLB live on separate Node-RED tabs.

const cfg = {
    version: "20260701-NL-DLB-Standalone-v1.0-TEST",
    enabled: 1,

    // Physical phase mapping. Multiple Zendures may share one phase.
    phases: ["L1", "L2", "L3"],

    // Per-device maximum charging power. Adjust for mixed-power systems.
    deviceMaxW: [2400, 2400, 2400],

    // Current limits.
    maxPhaseCurrentA: 25.0,
    softLimitA: 23.0,

    // P1 and conversion safety.
    voltageFallbackV: 215,
    p1MaxAgeSec: 15,
    failsafeA: 6,

    // Allocation.
    redistributionEnabled: 1,

    // Recovery ramp-up after DLB protection.
    rampUpWaitSec: 20,
    rampUpStepW: 250,
    rampUpStepIntervalSec: 10,

    // Normal soft-zone ramp-down.
    softRampDownStepW: 500,

    // Live writes are skipped below this change.
    liveMinChangeW: 25,

    // Warning repeat limiter.
    warnCooldownSec: 10
};

global.set('dlb_sa_cfg', cfg);
global.set('dlb_sa_engine_started_ms', Date.now());
global.set('dlb_sa_last_desired_batch', null);
global.set('dlb_sa_last_approved_w', [0, 0, 0]);
global.set('dlb_sa_ramp', [{armed:false,spaceSince:0,lastStep:0},{armed:false,spaceSince:0,lastStep:0},{armed:false,spaceSince:0,lastStep:0}]);
global.set('dlb_sa_status', 'startup_waiting_for_fresh_p1');
for (let p=1; p<=3; p++) {
    global.set('dlb_sa_current_L'+p, null);
    global.set('dlb_sa_current_ts_L'+p, 0);
    global.set('dlb_sa_voltage_L'+p, null);
}
node.status({fill:'yellow',shape:'ring',text:'DLB standalone: waiting for fresh P1'});
return null;

const p = Number(msg.phase || 0);
const value = Number(msg.payload);
if (!(p >= 1 && p <= 3) || !Number.isFinite(value)) {
    node.warn('[DLB standalone] Invalid P1 current update.');
    return null;
}
global.set('dlb_sa_current_L'+p, value);
global.set('dlb_sa_current_ts_L'+p, Date.now());
const c=[1,2,3].map(x=>global.get('dlb_sa_current_L'+x));
node.status({fill:'green',shape:'dot',text:new Date().toLocaleTimeString('nl-NL',{hour12:false})+' | '+c.map((v,i)=>'L'+(i+1)+' '+(Number.isFinite(Number(v))?Number(v).toFixed(2):'?')+'A').join(' | ')});
msg.dlb_live_trigger = true;
return msg;

const p = Number(msg.phase || 0);
const value = Number(msg.payload);
if (!(p >= 1 && p <= 3) || !Number.isFinite(value) || value < 150 || value > 280) return null;
global.set('dlb_sa_voltage_L'+p, value);
const v=[1,2,3].map(x=>global.get('dlb_sa_voltage_L'+x));
node.status({fill:'green',shape:'dot',text:new Date().toLocaleTimeString('nl-NL',{hour12:false})+' | '+v.map((n,i)=>'L'+(i+1)+' '+(Number.isFinite(Number(n))?Math.round(Number(n)):'?')+'V').join(' | ')});
return null;

// ============================================================================
// Standalone DLB engine — adapter request + P1-triggered live recalculation
// ============================================================================

function cloneValue(v){ return JSON.parse(JSON.stringify(v)); }
function cloneMessage(m, keepHttp){
    const c=Object.assign({},m);
    c.payload=cloneValue(m.payload);
    if(m.headers) c.headers=Object.assign({},m.headers);
    if(!keepHttp){ delete c.req; delete c.res; delete c._res; }
    return c;
}
function cloneBatch(batch, keepHttp){ return batch.filter(Boolean).map(m=>cloneMessage(m,keepHttp)); }
function clamp(v,a,b){ return Math.max(a,Math.min(b,v)); }
function phaseIndex(name, fallback){ const m=String(name||'').toUpperCase().match(/^L([123])$/); return m ? Number(m[1])-1 : fallback; }
function warnOnce(key,text,cooldown){
    const now=Date.now(); const k='dlb_sa_warn_'+key; const last=Number(global.get(k)||0);
    if(now-last >= cooldown*1000){ node.warn(text); global.set(k,now); }
}
function phaseGroups(phaseOf,count){
    return [0,1,2].map(p=>Array.from({length:count},(_,i)=>i).filter(i=>phaseOf[i]===p));
}
function allocate(wanted, maxW, phaseOf, phaseBudget, redistribute){
    const count=wanted.length;
    let target=wanted.map((v,i)=>clamp(Number(v)||0,0,Number(maxW[i])||0));
    const groups=phaseGroups(phaseOf,count);
    for(let p=0;p<3;p++){
        const total=groups[p].reduce((s,i)=>s+target[i],0);
        if(total>phaseBudget[p]+0.001 && total>0){ const r=phaseBudget[p]/total; groups[p].forEach(i=>target[i]*=r); }
    }
    if(redistribute){
        const requested=wanted.reduce((s,v)=>s+(Number(v)||0),0);
        let remaining=Math.max(0,requested-target.reduce((s,v)=>s+v,0));
        for(let guard=0;guard<20 && remaining>0.5;guard++){
            const used=[0,1,2].map(p=>groups[p].reduce((s,i)=>s+target[i],0));
            const candidates=Array.from({length:count},(_,i)=>i).filter(i=>maxW[i]-target[i]>0.5 && phaseBudget[phaseOf[i]]-used[phaseOf[i]]>0.5);
            if(!candidates.length) break;
            const before=remaining; let added=0;
            candidates.forEach(i=>{
                const p=phaseOf[i]; const share=before/candidates.length;
                const add=Math.min(share,maxW[i]-target[i],phaseBudget[p]-used[p]);
                if(add>0){target[i]+=add;used[p]+=add;added+=add;}
            });
            remaining-=added; if(added<0.1) break;
        }
    }
    target=target.map((v,i)=>Math.floor(clamp(v,0,maxW[i])));
    for(let p=0;p<3;p++){
        let excess=groups[p].reduce((s,i)=>s+target[i],0)-Math.floor(phaseBudget[p]);
        while(excess>0){ const g=groups[p].filter(i=>target[i]>0); if(!g.length) break; g.sort((a,b)=>target[b]-target[a]); const d=Math.min(excess,target[g[0]]); target[g[0]]-=d; excess-=d; }
    }
    return target;
}

const cfg=global.get('dlb_sa_cfg');
if(!cfg || !cfg.enabled){
    if(msg.dlb_batch){ msg.dlb_batch=msg.dlb_batch; return [msg,null]; }
    return null;
}
const isCall=Array.isArray(msg.dlb_batch);
const isLive=Boolean(msg.dlb_live_trigger);
let sourceBatch=isCall ? cloneBatch(msg.dlb_batch,true) : cloneBatch(global.get('dlb_sa_last_desired_batch')||[],false);
if(!Array.isArray(sourceBatch) || !sourceBatch.length) return null;

// Keep only the three device messages and make device order explicit.
sourceBatch=sourceBatch.filter(Boolean).sort((a,b)=>Number(a.dlb_device_index||0)-Number(b.dlb_device_index||0));
const count=Math.min(3,sourceBatch.length);
sourceBatch=sourceBatch.slice(0,count);
const hasChargeCommand=sourceBatch.some(m=>m && m.payload && m.payload.properties && Object.prototype.hasOwnProperty.call(m.payload.properties,'inputLimit'));
if(!hasChargeCommand){
    if(isCall){ msg.dlb_batch=sourceBatch; return [msg,null]; }
    return null;
}

if(isCall){ global.set('dlb_sa_last_desired_batch', cloneBatch(sourceBatch,false)); }
const wanted=sourceBatch.map(m=>Math.max(0,Number(m.payload.properties.inputLimit)||0));
const maxW=cfg.deviceMaxW.slice(0,count).map(v=>Math.max(0,Number(v)||2400));
const phaseOf=cfg.phases.slice(0,count).map((p,i)=>phaseIndex(p,i));
const groups=phaseGroups(phaseOf,count);
let previous=(global.get('dlb_sa_last_approved_w')||[0,0,0]).slice(0,count).map(v=>Math.max(0,Number(v)||0));
while(previous.length<count) previous.push(0);
const now=Date.now();
const started=Number(global.get('dlb_sa_engine_started_ms')||now);
const current=[0,1,2].map(p=>Number(global.get('dlb_sa_current_L'+(p+1))));
const currentTs=[0,1,2].map(p=>Number(global.get('dlb_sa_current_ts_L'+(p+1))||0));
const voltage=[0,1,2].map(p=>{const v=Number(global.get('dlb_sa_voltage_L'+(p+1)));return Number.isFinite(v)&&v>=150&&v<=280?v:Number(cfg.voltageFallbackV||215);});
const usedPhases=[0,1,2].filter(p=>groups[p].length && groups[p].some(i=>wanted[i]>0));
const fresh=usedPhases.map(p=>Number.isFinite(current[p]) && currentTs[p]>=started && now-currentTs[p]<=Number(cfg.p1MaxAgeSec)*1000);
const startupMissing=fresh.some(v=>!v) && usedPhases.some(p=>currentTs[p]<started);
const staleMissing=fresh.some(v=>!v) && !startupMissing;
let phaseBudget=[Infinity,Infinity,Infinity];
let hardTriggered=[]; let softTriggered=[];

for(let p=0;p<3;p++){
    const prevGroup=groups[p].reduce((s,i)=>s+previous[i],0);
    if(!groups[p].length){ phaseBudget[p]=0; continue; }
    if(!fresh[usedPhases.indexOf(p)] && usedPhases.includes(p)){
        phaseBudget[p]=startupMissing ? 0 : Number(cfg.failsafeA)*voltage[p];
        continue;
    }
    if(!usedPhases.includes(p)){
        // No requested charging on this phase; preserve zero target.
        phaseBudget[p]=0; continue;
    }
    const amps=current[p];
    if(amps>=Number(cfg.maxPhaseCurrentA)){
        hardTriggered.push(p);
        phaseBudget[p]=Math.max(0,prevGroup+(Number(cfg.maxPhaseCurrentA)-amps)*voltage[p]);
    } else if(amps>Number(cfg.softLimitA)){
        softTriggered.push(p);
        const exact=Math.max(0,prevGroup+(Number(cfg.softLimitA)-amps)*voltage[p]);
        phaseBudget[p]=Math.max(exact,Math.max(0,prevGroup-Number(cfg.softRampDownStepW||500)));
    } else {
        phaseBudget[p]=Math.max(0,prevGroup+(Number(cfg.softLimitA)-amps)*voltage[p]);
    }
}

if(startupMissing){
    global.set('dlb_sa_status','startup_waiting_for_fresh_p1');
} else if(staleMissing){
    global.set('dlb_sa_status','p1_failsafe');
    warnOnce('p1','[DLB standalone] P1 current data stale/missing; fail-safe charging limit is active.',Number(cfg.warnCooldownSec||10));
} else if(hardTriggered.length){
    global.set('dlb_sa_status','hard_throttling');
    warnOnce('hard','[DLB standalone] Hard phase-current protection active on '+hardTriggered.map(p=>'L'+(p+1)).join(', ')+'.',Number(cfg.warnCooldownSec||10));
} else if(softTriggered.length){
    global.set('dlb_sa_status','soft_throttling');
} else {
    global.set('dlb_sa_status','normal');
}

let target=allocate(wanted,maxW,phaseOf,phaseBudget,Boolean(cfg.redistributionEnabled));

// Controlled ramp-up after any phase protection.
let ramps=global.get('dlb_sa_ramp')||[{armed:false,spaceSince:0,lastStep:0},{armed:false,spaceSince:0,lastStep:0},{armed:false,spaceSince:0,lastStep:0}];
for(let p=0;p<3;p++){
    const g=groups[p]; if(!g.length) continue;
    const prevGroup=g.reduce((s,i)=>s+previous[i],0);
    const targetGroup=g.reduce((s,i)=>s+target[i],0);
    const wantedGroup=g.reduce((s,i)=>s+wanted[i],0);
    if(targetGroup<prevGroup-0.5 || phaseBudget[p]<wantedGroup-0.5){ ramps[p].armed=true; ramps[p].spaceSince=0; }
    if(ramps[p].armed && targetGroup>prevGroup+0.5){
        if(!ramps[p].spaceSince) ramps[p].spaceSince=now;
        const waited=now-ramps[p].spaceSince>=Number(cfg.rampUpWaitSec||0)*1000;
        let allowed=prevGroup;
        if(waited){
            const intervalOk=!ramps[p].lastStep || now-ramps[p].lastStep>=Number(cfg.rampUpStepIntervalSec||0)*1000;
            if(Number(cfg.rampUpStepW||0)<=0) allowed=targetGroup;
            else if(intervalOk){ allowed=Math.min(targetGroup,prevGroup+Number(cfg.rampUpStepW)); ramps[p].lastStep=now; }
        }
        if(allowed<targetGroup-0.5){
            const growth=targetGroup-prevGroup;
            g.forEach(i=>{ const base=previous[i]; const inc=Math.max(0,target[i]-base); target[i]=Math.floor(base+(growth>0?inc*(allowed-prevGroup)/growth:0)); });
        }
    } else if(targetGroup<=prevGroup+0.5){ ramps[p].spaceSince=0; }
    if(targetGroup>=wantedGroup-0.5 && !softTriggered.includes(p) && !hardTriggered.includes(p)){ ramps[p]={armed:false,spaceSince:0,lastStep:0}; }
}
global.set('dlb_sa_ramp',ramps);

const approvedBatch=cloneBatch(sourceBatch,isCall);
approvedBatch.forEach((m,i)=>{
    if(m && m.payload && m.payload.properties && Object.prototype.hasOwnProperty.call(m.payload.properties,'inputLimit')){
        m.payload.properties.inputLimit=Math.max(0,Math.floor(target[i]||0));
    }
    m.dlb_original_input_limit=wanted[i];
    m.dlb_approved_input_limit=Math.max(0,Math.floor(target[i]||0));
    m.dlb_engine_version=cfg.version;
});
const change=target.reduce((mx,v,i)=>Math.max(mx,Math.abs(v-previous[i])),0);
global.set('dlb_sa_last_approved_w',target.concat([0,0,0]).slice(0,3));
global.set('dlb_sa_last_result',{wanted:wanted,approved:target,current:current,voltage:voltage,status:global.get('dlb_sa_status'),timestamp:now});

const status=global.get('dlb_sa_status');
if(status==='normal') node.status({fill:'green',shape:'dot',text:'Normal | '+target.join('/')+' W'});
else if(status==='soft_throttling') node.status({fill:'yellow',shape:'dot',text:'Soft throttle | '+target.join('/')+' W'});
else if(status==='hard_throttling') node.status({fill:'red',shape:'dot',text:'HARD throttle | '+target.join('/')+' W'});
else node.status({fill:'yellow',shape:'ring',text:status+' | '+target.join('/')+' W'});

if(isCall){ msg.dlb_batch=approvedBatch; msg.dlb_adapter_result=true; return [msg,null]; }
if(isLive && change>=Number(cfg.liveMinChangeW||25)){
    const live={payload:null,dlb_batch:approvedBatch,dlb_live_write:true};
    // Live writes must not carry the original HTTP request/response objects.
    live.dlb_batch.forEach(m=>{delete m.req;delete m.res;delete m._res;});
    return [null,live];
}
return null;

const batch=Array.isArray(msg.dlb_batch)?msg.dlb_batch:[];
const out=[null,null,null];
batch.forEach(m=>{
    const i=Number(m.dlb_device_index||0)-1;
    if(i>=0 && i<3) out[i]=m;
});
return out;

const status=Number(msg.statusCode||0);
if(status>=200 && status<300) return null;
const device=Number(msg.dlb_device_index||0);
const detail=msg.error?(msg.error.message||String(msg.error)):('HTTP '+(status||'unknown'));
node.warn('[DLB standalone live] Zendure '+(device||'?')+' write failed: '+detail+'.');
return null;
